#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N,K;
    cin>>N>>K;
    int T=N+K;
    vector<int> id(T);
    vector<double> x(T),y(T);
    vector<char> tp(T);
    vector<int> robots;
    for(int i=0;i<T;i++){
        cin>>id[i]>>x[i]>>y[i]>>tp[i];
        if(tp[i]=='R') robots.push_back(i);
    }
    int NR=robots.size();
    // Build all edges, sort by distance (Kruskal for bottleneck/MST)
    struct E{int u,v;double w;};
    vector<E> edges;
    for(int i=0;i<T;i++) for(int j=i+1;j<T;j++){
        double dx=x[i]-x[j],dy=y[i]-y[j];
        edges.push_back({i,j,sqrt(dx*dx+dy*dy)});
    }
    sort(edges.begin(),edges.end(),[](const E&a,const E&b){return a.w<b.w;});
    vector<int> par(T);
    iota(par.begin(),par.end(),0);
    function<int(int)> find=[&](int a)->int{return par[a]==a?a:par[a]=find(par[a]);};
    vector<E> tree;
    set<int> robotSet(robots.begin(),robots.end());
    int components=NR; // count of distinct robot components
    for(auto&e:edges){
        if(components<=1) break;
        int a=find(e.u),b=find(e.v);
        if(a==b) continue;
        // Count how merging affects robot components
        // We track robot components separately isn't easy; just merge and count
        par[a]=b;
        tree.push_back(e);
        // Recount robot components
    }
    // Recount: check if all robots connected
    // Now prune relay leaves
    set<int> usedNodes;
    for(auto&e:tree){usedNodes.insert(e.u);usedNodes.insert(e.v);}
    // Build adjacency, prune relay leaves iteratively
    map<int,set<int>> adj;
    for(int i=0;i<(int)tree.size();i++){adj[tree[i].u].insert(i);adj[tree[i].v].insert(i);}
    vector<bool> alive(tree.size(),true);
    bool changed=true;
    while(changed){changed=false;
        for(auto&[node,eset]:adj){
            if(tp[node]!='C') continue;
            int cnt=0;for(int ei:eset)if(alive[ei])cnt++;
            if(cnt<=1){for(int ei:eset)if(alive[ei]){alive[ei]=false;changed=true;}}}
    }
    set<int> relays;
    vector<E> finalEdges;
    for(int i=0;i<(int)tree.size();i++) if(alive[i]){
        finalEdges.push_back(tree[i]);
        if(tp[tree[i].u]=='C') relays.insert(tree[i].u);
        if(tp[tree[i].v]=='C') relays.insert(tree[i].v);
    }
    if(relays.empty()) cout<<"#\n";
    else{bool f=true;for(int c:relays){if(!f)cout<<"#";cout<<id[c];f=false;}cout<<"\n";}
    {bool f=true;for(auto&e:finalEdges){if(!f)cout<<"#";cout<<id[e.u]<<"-"<<id[e.v];f=false;}cout<<"\n";}
}
